const upload=/^(?:\/uploads\/[a-f0-9-]+\.(?:jpg|png|webp)|\/assets\/examples\/(?:torres360-demo\.svg|ferrari-458-[12]\.jpg)|\/assets\/photo-tour\/bmw-(?:panorama\.png|dashboard\.jpg|seats\.jpg)|\/assets\/tour-demo\/(?:exterior-\d{2}|interior-delantero|interior-trasero|tablero|maletero)\.svg)$/;
export function normalizeTour(input){if(!input||input.enabled!==true)return{enabled:false,exterior:[],scenes:[]};const exterior=input.exterior||[],scenes=input.scenes||[];if(!Array.isArray(exterior)||exterior.length>72||exterior.some(p=>!upload.test(p)))throw Error('Torres 360 admite hasta 72 fotos exteriores subidas.');if(exterior.length>0&&exterior.length<8)throw Error('Para el giro exterior carga al menos 8 fotos en orden; recomendamos 36.');if(!Array.isArray(scenes)||scenes.length>8)throw Error('Torres 360 admite hasta 8 vistas interiores o de detalle.');const result=scenes.map((s,i)=>{if(!['panorama','photo'].includes(s.kind)||!upload.test(s.photo))throw Error('Revisa las fotos y el formato de las vistas Torres 360.');const label=String(s.label||'').trim().slice(0,70);if(!label)throw Error('Pon un nombre a cada vista Torres 360.');const id=/^[a-z0-9-]{1,60}$/.test(s.id)?s.id:'scene-'+i;const points=Array.isArray(s.points)?s.points.slice(0,12).filter(p=>p&&/^[a-z0-9-]{1,60}$/.test(p.target)&&Number.isFinite(p.yaw)&&Math.abs(p.yaw)<=Math.PI*2&&Number.isFinite(p.pitch)&&Math.abs(p.pitch)<=Math.PI/2).map(p=>({target:p.target,yaw:p.yaw,pitch:p.pitch,label:String(p.label||'Cambiar de vista').slice(0,70)})):[];return{id,label,kind:s.kind,photo:s.photo,points,...(Number.isFinite(s.yaw)?{yaw:Math.max(-Math.PI*2,Math.min(Math.PI*2,s.yaw))}:{}),...(Number.isFinite(s.pitch)?{pitch:Math.max(-1.4,Math.min(1.4,s.pitch))}:{})};});if(!exterior.length&&!result.length)throw Error('Añade fotos a Torres 360 o desactiva la opción antes de guardar.');return{enabled:true,photographicDemo:result.some(s=>s.photo.startsWith('/assets/photo-tour/')),demo:exterior.some(p=>p.startsWith('/assets/tour-demo/'))||result.some(s=>s.photo.startsWith('/assets/tour-demo/')),exterior,scenes:result};}
